module forest_constructor (input clk, input rst_n, input start, input [3:0] V, input [7:0] target_degree [0:7], output reg valid, output reg [3:0] edge_u [0:13], output reg [3:0] edge_v [0:13], output reg [4:0] edge_count, output reg done); reg [2:0] state; always_ff @(posedge clk) begin if (!rst_n) begin state <= 0; valid <= 0; edge_count <= 0; done <= 0; end else begin case (state) 0: if (start) state <= 1; 1: state <= 4; 4: done <= 1; endcase end end endmodule